INSERT INTO static.map_landmarks ("landmarkID", "landmarkName", "description", "radius", "x", "y", "z", "importance") VALUES
    (1, 'EVE Gate', 'In the system of New Eden sits the impenetrable EVE Gate. Thousands of years ago the forefathers of all the human races used the gate to travel to the world of EVE. But the gate has been closed for a long time, a catastrophe that destroyed all planets in the New Eden system and plunged the fragile human settlements to the brink of extinction. Anyone foolish enough to get too close to the gate today will be ripped apart by the magnetic storms that still surround the massive gate.', 1.27496337891e+16, -2.84886865234e+17, -3.59242553711e+16, 6.57202941895e+16, 5),
    (3, 'Amarr Home Worlds', '', 8000000000000000.0, -2.04748693848e+17, 4.02383789063e+16, 5.76212768555e+16, 4),
    (4, 'Amarr Empire', 'The largest of the five main empires, the Amarr Empire is a sprawling patch-work of feudal-like provinces held together by the might of the emperor. Religion has always played a big part in Amarrian politics and the Amarrians believe they are the rightful masters of the world, souring their relations with their neighbours. Another source of ill-feelings on part of the other empires is the fact that the Amarrians embrace slavery.', 1.43699316406e+17, -2.11238818359e+17, 1722270995380.0, 7.06287353516e+16, 0),
    (5, 'Minmatar Republic', 'The Minmatar Republic was formed over a century ago when the Minmatars threw out their Amarrians overlords in what is known as the Minmatar Rebellion. The Minmatars had the support of the Gallente Federation and to this day the two nations are close allies. Yet only a quarter of the Minmatars reside within the Republic, the rest is scattered around the world, including a large portion still enslaved within the Amarr Empire. Minmatars are independant and proud, with strong will and many tribal traditions.', 9.94996398926e+16, -8.80286010742e+16, 141912640538.0, -2.8733605957e+16, 0),
    (6, 'Caldari State', 'The Caldari State is ruled by several mega-corporations, there is no central government to speak off, all territories within the state are owned and ruled by a corporation. Duty and discipline are required traits in Caldari citizens, plus unquestioning loyality to the corporation they live to serve. The corporations compete aggressively amongst themselves and with companies outside the State, resulting in a highly capitalistic society.', 1.03921569824e+17, -1.35868737793e+17, -7529594749210.0, -1.19848132324e+17, 0),
    (7, 'Gallente Federation', 'The Gallente Federation encompasses several races, the Gallenteans the largest by far. The Federation is democratic and very liberal in a world full of dictators and oligarchies. The Caldari State was once part of the Federation, but a severe dispute resulted in their departure and a long war between the Gallente Federation and the Caldari State. The Gallenteans are the masters of pleasure and entertainment and their rich trade empire has given the world many of its most glorious and extravagant sights.  ', 1.07039257813e+17, -2.23934619141e+17, -4200590029360.0, -5.51128845215e+16, 0),
    (8, 'Jove Empire', 'The Jove Empire is isolated from the rest of the world to all but a selected few. The Jovians are a mystery to the other races, fueled not only by their elusiveness, but also their highly advanced technology, eons ahead of the other races. The Jovians have been civilized longer than any other race in the world of EVE and have gone through several golden ages, now long-since shrouded in the past. The current Jovian Empire is only a pale shadow of its former self, mainly because of the Jovian Disease - a psychological disorder that is always fatal.', 9.90536010742e+16, 9537117767330000.0, -261083897203.0, -2.53588720703e+17, 0),
    (9, 'Ammatar', 'The Ammatars are part of the Amarr Empire, but are of Minmatar origin. During the time the Amarrians occupied the Minmatar home worlds one of the Minmatar tribes, the Nefantars, collaborated heavily with the Amarrians. The Nefantars fled Minmatar space during the Minmatar Rebellion and the Amarr Emperor set them up in Amarr controlled areas close to Minmatar space. Soon everyone had started callig them Ammatars. Today, the Ammatars enjoy a semi-autonomy in their own space and are still embroiled in war with their former Minmatar brethren.', 8.11693115234e+16, -8.79526977539e+16, 550164375454.0, 6.53263305664e+16, 1),
    (10, 'Khanid Kingdom', 'The Khanid Kingdom, also known as the Dark Amarr, was founded a few centuries ago when the last Amarr Emperor was chosen. Khanid was one of the royal heirs at the time and, in accordance with tradition, should have killed himself after failing to become emperor. This Khanid refused to do and splis his vast domains from the Amarr Empire. The empire retaliated, but only managed to conquer some of the vulnerable outer regions from Khanid. The Kingdom still upholds many of the tradition of Amarr society, but has also wholeheartedly embraced the customs of others, mainly the Caldari. Many visitors to the Kingdom feel like it is a surreal mix of the Amarr and Caldari empires. ', 7.41486633301e+16, -2.96470825195e+17, 27066481113400.0, 1.3949317627e+17, 1),
    (11, 'Fountain', 'The Fountain region was one of the first areas opened up to public colonization by CONCORD - it was intended to be the ''fountain of inter-stellar cooperation and prosperity''. Although the colonization process began fine enough, in time the lack of empire protection and coherent regional authority began to tell. Slowly at first, then more surely, pirate clans and bandit gangs started taking over the settlements one by one. In the end the region was totally in the hands of pirate kings and robber barons. Later, these criminal elements were the foundation of the illegal booster industry and today the region is best known for its neural booster production, mainly in the form of the Serpentis Corporation.', 8.70047485352e+16, -4.31159277344e+17, 66517031192800.0, 2205274581910000.0, 1),
    (12, 'Curse', 'Curse is the old home of the Jove Empire. The Jovians departed their home centuries ago after the fall of their Second Empire and set themselves up in their current whereabouts to form the Third (and current) Empire. The cause of the departure was the dreaded Jove Disease, which only Jovians could catch. Having found no cure for the disease the Jovians decided to leave their home worlds in a desperate bid to rid themselves of the disease once and for all. The attempte failed. Today, the former Jovian systems are occupied by the Angel Cartel, the strongest pirate clan in the world of EVE. Rumor has it that the source of their power is old Jovian technology scavanged from the relics of old Jovian stations and settlements.', 5.67119445801e+16, 3564098739620000.0, -1551700006.53, 1.53965844727e+17, 1),
    (13, 'Great Wildlands', 'The Great Wildlands area has been the bastard child of all the empires at some stage. During the Minmatar Rebellion it acted as a base for Minmatar guerillas and was also the avenue through which the Amarrians and Jovians fought their war at the same time. The Caldari invested heavily in the region at one point searching for rare minerals, but later pulled out due to ownership conflicts with the other empires. Today the region is a mismatch of pirate havens and mining facilities. Its jump routes are still used as short cuts, but only by those bold enough. The nomad Thukker tribe is a common sight in the Great Wildlands and is the closest thing to a home to them.', 6.97843322754e+16, 3.46159881592e+16, 657644448802.0, 7.65537109375e+16, 1),
    (14, 'The Syndicate', '', 6.89307006836e+16, -3.15631054688e+17, 3285689651970.0, -6.22300415039e+16, 1),
    (15, 'Outer Ring', 'The Outer Ring is a mineral rich are controlled by Outer Ring Excavations, which was the first company to start operating in the system. The Outer Ring Excavations (or ORE) is an independatly run mining company, the largest of its kind. ORE is very envious of their priced asteroid belts and have employed the service of Mordu''s Legion to protect the region.', 5.66980957031e+16, -3.91229150391e+17, -11646238714500.0, -9.00422973633e+16, 1),
    (16, 'Stain', '', 6.32297241211e+16, -1.5292923584e+17, 5929109081630.0, 3.37768994141e+17, 1),
    (17, 'Venal', '', 7.82541809082e+16, -1.46257287598e+17, -8899687230590.0, -3.06315283203e+17, 1),
    (18, 'The Cauldron', 'Khanid - Amarr', 3.71203094482e+16, -3.32093041992e+17, 3536401316520.0, 7.46816711426e+16, 1),
    (19, 'Trace Cosmos', 'West Gallente - Amarr', 3.32288085938e+16, -3.43803149414e+17, 29480636119800.0, 8431810760500000.0, 1),
    (20, 'Point of no Return', 'center of the world', 8000000000000000.0, 0.0, 0.0, 0.0, 1),
    (21, 'Black Rise', 'Gallente - Caldari', 3.56444641113e+16, -2.20403857422e+17, -3218077868220.0, -1.443203125e+17, 1),
    (22, 'Divinity''s Edge', 'Ammatar - Great Wildlands', 3.5783380127e+16, -2.42091537476e+16, 280828960240.0, 7.20049377441e+16, 1),
    (23, 'Vapor Sea', 'south of Amarr', 7.11783569336e+16, -2.24672631836e+17, 10845974087700.0, 2.11340600586e+17, 1),
    (24, 'Pool  of Radiance', 'inside sansha', 2.60809661865e+16, -1.47403015137e+17, 17245195806000.0, 2.86624682617e+17, 1),
    (25, 'Cord of the Elements', 'syndicate split', 2.8993963623e+16, -3.17870581055e+17, -3618441894650.0, -6.67926635742e+16, 1),
    (26, 'Ginnungagap', 'east of Minmatar', 3.11600860596e+16, 1.96950439453e+16, -37010508822.3, -4.89585449219e+16, 1),
    (27, 'Golgothan Fields', '', 0.0, -8968666578880000.0, -1931296768510000.0, -1.24558824421e+16, 5),
    (29, 'The Myridian Strip', '', 0.0, -1.44283830156e+17, 1.47917870973e+16, 2.08254493588e+16, 5),
    (30, 'R55 Colonial Ruins', '', 0.0, -2.33253181242e+17, 7.74476452545e+16, -1.75038095915e+17, 5),
    (31, 'Serpent''s Coil', '', 0.0, -2.50627818165e+17, 8.87132945013e+16, -8.82529136856e+16, 5),
